    enonce: "<span dir=\"ltr\" class=\"expr pt\">ADE</span> مثلّث، <span dir=\"ltr\" class=\"expr pt\">B</span> نقطة من <span dir=\"ltr\" class=\"expr pt\">[AD]</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> نقطة من <span dir=\"ltr\" class=\"expr pt\">[AE]</span> حيث <span dir=\"ltr\" class=\"expr pt\">(BC) // (DE).</span><br><span dir=\"ltr\" class=\"expr pt\">AB = 2,5</span> و <span dir=\"ltr\" class=\"expr pt\">BC = 6,5</span> و <span dir=\"ltr\" class=\"expr pt\">DE = 13</span> و <span dir=\"ltr\" class=\"expr pt\">CE = 6.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 83 162\" width=\"83\" height=\"162\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(-24.6 -14.0)\"><line x1=\"43.2\" y1=\"146.8\" x2=\"86.4\" y2=\"146.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"43.2\" y1=\"146.8\" x2=\"43.2\" y2=\"43.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"86.4\" y1=\"146.8\" x2=\"43.2\" y2=\"43.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"64.8\" y1=\"146.8\" x2=\"43.2\" y2=\"95.0\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"43.2\" cy=\"146.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"37.4\" y=\"164.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"64.8\" cy=\"146.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"68.8\" y=\"165.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"43.2\" cy=\"95.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"35.2\" y=\"86.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"86.4\" cy=\"146.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"96.8\" y=\"161.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text><circle cx=\"43.2\" cy=\"43.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"40.5\" y=\"32.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب <span dir=\"ltr\" class=\"expr pt\">AD.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> أحسب <span dir=\"ltr\" class=\"expr pt\">x = AC.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 2,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 6,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 13</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">AD.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AD.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">13</span><span class=\"den\">2</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 13</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">5</span><span class=\"den\">2</span></span>. و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث ADE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">B ∈ (AD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (AE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AB</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AC</span><span class=\"den\">AE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BC</span><span class=\"den\">DE</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">6,5</span><span class=\"den\">13</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">2,5</span><span class=\"den\">AD</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AD = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AD = 5</span>"},{"quoi":"2)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">x = AC.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AC.</span> نختار النّسبة و الجزء الباقي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">13</span><span class=\"den\">2</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 13</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 6.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث ADE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">B ∈ (AD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (AE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AB</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AC</span><span class=\"den\">AE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BC</span><span class=\"den\">DE</span></span>"},{"quoi":"القاعدة","math":"إذا عُلمت النّسبة و عُلم الجزء الباقي، أمكن حساب الطولين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 6,5</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 13</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 6</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AC = 6</span>  ، لأنّ النّسبة <span class=\"frac\" dir=\"ltr\"><span class=\"num\">6,5</span><span class=\"den\">13</span></span> و الفرق 6"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AC = 6</span>"}],
